// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Attacker attacker;

    function setUp() public {
        // deploy c with a fresh Log as required
        c = new X_WALLET(address(new Log()));
        // deploy the attacker helper that will re-enter once during Collect
        attacker = new Attacker(c);
    }

    // fuzzed parameters: deposit amount (value sent to Put), collect amount, and unlockTime offset
    function testFuzz_property(uint256 deposit, uint256 collectAmt, uint256 unlockOffset) public {
        vm.assume(deposit <= VALUE_CAP);
        // keep values within reasonable bounds and ensure deposit >= collectAmt when desired
        deposit = bound(deposit, 1 wei, 10 ether);
        collectAmt = bound(collectAmt, 1 wei, 10 ether);
        // unlockOffset will be used to set unlockTime relative to block.timestamp
        unlockOffset = bound(unlockOffset, 0, 1000);

        address payable atk = payable(address(attacker));

        // fund the attacker externally so it can call Put and pay gas
        vm.deal(atk, deposit + 1 ether);

        // attacker will act as msg.sender for Put to create an Acc entry
        vm.prank(atk);
        c.Put{value: deposit}(block.timestamp + unlockOffset);

        // ensure the preconditions: the holder has at least MinSum and enough balance
        // If MinSum requirement not met, Collect reverts / is no-op; ensure we meet it
        uint256 min = c.MinSum();
        // If deposit < min, increase deposit by sending extra to the contract via Put again
        if (deposit < min) {
            vm.deal(atk, min - deposit + 1 ether);
            vm.prank(atk);
            c.Put{value: min - deposit}(block.timestamp + unlockOffset);
            deposit = deposit + (min - deposit);
        }

        // warp time so unlockTime has passed
        vm.warp(block.timestamp + unlockOffset + 1);

        // configure the attacker with the collect amount to attempt to withdraw
        attacker.setCollectParams(collectAmt);

        // Now perform the Collect from attacker and record whether the CALL returned normally
        bool ok;
        // run as attacker
        vm.prank(atk);
        try c.Collect{value: 0}(collectAmt) { ok = true; } catch { ok = false; }

        // The invariant (general rule): during a single external Collect invocation, the total ETH
        // actually received by the caller (as observed by the attacker helper's recordedReceived)
        // must be <= collectAmt for the correct contract. The mutant (without require) can re-enter and
        // cause the contract to send more than collectAmt in that one top-level Collect call.
        uint256 received = attacker.recordedReceived();

        // Assert the universal rule: for all admissible inputs the reference satisfies received <= collectAmt
        // (this will hold for the correct contract for all inputs; the mutant will allow a failing case where received > collectAmt)
        assertTrue(received <= collectAmt);
    }
}

// Attacker helper: when it receives ETH, it re-enters C.collect exactly once to try to drain more.
contract Attacker {
    X_WALLET immutable target;
    uint256 public recorded; // total received during the single top-level Collect
    uint256 private toCollect;
    bool private reentered;

    constructor(X_WALLET _c) {
        target = _c;
    }

    function setCollectParams(uint256 _amt) external {
        toCollect = _amt;
        recorded = 0;
        reentered = false;
    }

    // fallback to receive the payment from C.Collect: record the value and re-enter exactly once.
    receive() external payable {
        recorded += msg.value;
        // re-enter exactly once: call Collect again to attempt to withdraw more than allowed
        if (!reentered) {
            reentered = true;
            // call Collect with the same amount; this will be executed during the same top-level Collect call
            // If the target has the require(!locked_) check, re-entry will revert or be prevented; otherwise it may succeed
            // Use low-level call to avoid bubbling reverts to this receive if desired; but we use the external call
            // on target which will behave as per contract under test.
            try target.Collect{value: 0}(toCollect) { } catch { }
        }
    }

    // helper for the test to read how much this attacker got during the invocation
    function recordedReceived() external view returns (uint256) {
        return recorded;
    }
}
